#include <string>
#include <vector>
#include <algorithm>
#include <climits>
#include <cmath>

class Solution {
public:
    int dist(int p1, int p2) {
        if (p1 == 26 || p2 == 26) return 0;
        return std::abs(p1 / 6 - p2 / 6) + std::abs(p1 % 6 - p2 % 6);
    }
    int minimumDistance(std::string word) {
        std::vector<int> dp(27, INT_MAX / 2);
        dp[26] = 0;
        for (size_t i = 0; i < word.size(); ++i) {
            int cur = word[i] - 'A';
            int prev = (i == 0) ? 26 : (word[i - 1] - 'A');
            std::vector<int> nxt(27, INT_MAX / 2);
            for (int other = 0; other < 27; ++other) {
                if (dp[other] >= INT_MAX / 2) continue;
                nxt[other] = std::min(nxt[other], dp[other] + dist(prev, cur));
                nxt[prev] = std::min(nxt[prev], dp[other] + dist(other, cur));
            }
            dp = std::move(nxt);
        }
        int ans = INT_MAX;
        for (int v : dp) ans = std::min(ans, v);
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    private int dist(int p1, int p2) {
        if (p1 == 26 || p2 == 26) return 0;
        return Math.abs(p1 / 6 - p2 / 6) + Math.abs(p1 % 6 - p2 % 6);
    }
    public int minimumDistance(String word) {
        int[] dp = new int[27];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[26] = 0;
        for (int i = 0; i < word.length(); i++) {
            int cur = word.charAt(i) - 'A';
            int prev = (i == 0) ? 26 : (word.charAt(i - 1) - 'A');
            int[] nxt = new int[27];
            Arrays.fill(nxt, Integer.MAX_VALUE / 2);
            for (int other = 0; other < 27; other++) {
                if (dp[other] >= Integer.MAX_VALUE / 2) continue;
                nxt[other] = Math.min(nxt[other], dp[other] + dist(prev, cur));
                nxt[prev] = Math.min(nxt[prev], dp[other] + dist(other, cur));
            }
            dp = nxt;
        }
        int ans = Integer.MAX_VALUE;
        for (int v : dp) ans = Math.min(ans, v);
        return ans;
    }
}

var minimumDistance = function(word) {
    const dist = (p1, p2) => {
        if (p1 === 26 || p2 === 26) return 0;
        return Math.abs(Math.floor(p1 / 6) - Math.floor(p2 / 6)) + Math.abs((p1 % 6) - (p2 % 6));
    };
    let dp = new Int32Array(27).fill(1e9);
    dp[26] = 0;
    for (let i = 0; i < word.length; i++) {
        const cur = word.charCodeAt(i) - 65;
        const prev = (i === 0) ? 26 : (word.charCodeAt(i - 1) - 65);
        const nxt = new Int32Array(27).fill(1e9);
        for (let other = 0; other < 27; other++) {
            if (dp[other] >= 1e9) continue;
            const cost1 = dp[other] + dist(prev, cur);
            if (cost1 < nxt[other]) nxt[other] = cost1;
            const cost2 = dp[other] + dist(other, cur);
            if (cost2 < nxt[prev]) nxt[prev] = cost2;
        }
        dp = nxt;
    }
    let ans = 1e9;
    for (let i = 0; i < 27; i++) if (dp[i] < ans) ans = dp[i];
    return ans;
};
